def handle_start(user_id, username):
    return f"👋 Welcome {username} to Aonik Hosting Bot Services! Use /help for available actions."

def handle_status():
    return {
        "status": "online",
        "load": "optimal",
        "version": "3.1-stable"
    }

const express = require('express');
const app = express();
const PORT = process.env.PORT || 3000;

app.use(express.json());

app.get('/', (req, res) => {
  res.json({
    service: 'AONIK Node API Service',
    status: 'operational',
    node: 'Edge-SG-02',
    timestamp: new Date().toISOString()
  });
});

app.get('/api/health', (req, res) => {
  res.json({ status: 'ok', uptime: process.uptime(), memory: process.memoryUsage() });
});

app.listen(PORT, () => {
  console.log(`[AONIK HOSTING] Node.js server running on port ${PORT}`);
});

{
  "name": "aonik-node-app",
  "version": "1.0.0",
  "main": "server.js",
  "scripts": {
    "start": "node server.js",
    "dev": "nodemon server.js"
  },
  "dependencies": {
    "express": "^4.19.2",
    "cors": "^2.8.5",
    "dotenv": "^16.4.5"
  }
}

